        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "la pianta uomo nasce in Italia, non seconda a nessuno", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Non scambiammo una parola. Ma gli occhi nostri s'intesero nell'affetto che ci legava da tanto tempo.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Coraggioso! All'avanguardia del progresso noi vi seguiremo", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "I clericali sono sudditi e militi di una potenza straniera, autorità mista ed universale, spirituale e politica, che comanda e non si lascia discutere, semina discordie e corrompe.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Io sono cristiano, sono un buon cristiano, e parlo a dei buoni cristiani; io amo e venero la religione di Cristo, perché Gesù Cristo è venuto al mondo per sottrarre l'umanità alla servitù", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il prete è l'assassino dell'anima poiché in tutti i tempi egli ha fomentato l'ignoranza e perseguito la scienza.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "L'Internazionale è il sole dell'avvenire.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Io non tollero all'Internazionale, come non tollero alla monarchia, le sue velleità antropofaghe.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Io son fatto per romper i coglioni a mezza umanità, e l'ho giurato", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Con donne simili una nazione non può morire.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La spada è un delitto, come la pena di morte è un abuso, come la conquista è una ingiuria.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Facciamo della guerra un anacronismo, e del lavoro un inno allo Eterno.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Noi siamo giunti sulla terra di rifugio, e dobbiamo il miglior contegno ai generosi ospiti", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Ma rammento loro che l'Italia non deve rimanere nell'obbrobrio, e che meglio è morire che vivere schiavi dello straniero.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Obbedisco.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Occorre una nuova conquista! L' abolizione del privilegio elettorale.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Per avere, bisogna volere; bisogna insistere fino a scopo compiuto.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Quando io, sulle coste Americane dell'oceano ho potuto dire a degli schiavi \"Voi siete liberi\", quello fu certamente il più bel momento della mia vita.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Qui si decidono i destini dell'Italia. Una battaglia vinta sotto Capua ci darà nelle mani l'Italia.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Qui si fa l'Italia o si muore.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Roma o morte!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Se non vi fosse storia romana, ove imparammo una patria comune, se giovane non avessi vagato tra le macerie del gigante delle grandezze terrestri, io non saprei di essere Italiano.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Solo al veder un uccellino con la zampa spezzata mi fa star male.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Tempi borgiani.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Tra le malizie gesuitiche dei tonsurati vi è pur quella di fingersi protettori delle belle arti", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il fenomeno della insaziabile tendenza pretina al solo godimento dei beni materiali è cosa a tutti nota", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Agli stolti l'ignoranza e la miseria, per la maggior gloria di Dio; ai preti la crapula, ricchezze e lussuria, sempre per la maggiore gloria di Dio!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La seconda sorgente di ricchezze i preti la derivavano al capezzale degl'infermi", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La confessione! quell'arma terribile del pretismo, elemento primo delle sue seduzioni", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Giustizia! Santa parola, prostituita, derisa dai potenti della terra!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "L'Europa! Ove chi fatica muore dalla fame e gli oziosi nuotano nell'abbondanza e nella lussuria", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Dacché nella famiglia umana, vi furono uomini che svestirono le forme umane per farsi impostori, cioè preti, dacché vi furono preti nel mondo, vi furono torture.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Non si sa se più scellerati i preti e chi li sorregge o più stupido questo miserabile popolo che li soffre nel suo seno", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Le statistiche assicurano essere gli omicidi in Roma più frequenti che in alcun'altra parte", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Tolte le crudeltà commesse dai briganti assoldati dai preti, quella classe di gente, ha mostrato in questi ultimi tempi una tenacità ed una bravura degna di miglior causa", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La storia del Papato è storia di briganti.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Un altro fatto che attesta grandemente il progresso umano della nostr'età è l'avvicinamento dell'aristocrazia al popolo.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Chi negherà che le popolazioni dell'Italia meridionale non fossero migliori, perché meglio governate, nel 1860 che non lo sieno al giorno d'oggi?", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Dio vi si adora come si deve, col culto dell'anima, senza sfarzo, nel grandioso tempio della natura", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Professa idee di tolleranza universale e vi si uniforma, ma i preti, come preti non li accetta perché egli non intende siano tollerati malfattori, ladri e assassini", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Egli ha passato la sua vita colla speranza di vedere nobilitata la plebe e ne ha propugnato dovunque i diritti e sempre.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Quando si pensa essere sì pochi che godono o per meglio dire monopolizzano i benefici della società incivilita e che tanti sono i sofferenti, non si può fare a meno di dubitare", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La professione del prete è questa: godere e far credere alle moltitudini stupide ch'egli soffre di privazioni e di disagi.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il prete che insegna Dio è un mentitore, poiché nulla egli sa di Dio.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il prete, sacerdote delle tenebre, colpito nelle sue miserie e nelle sue menzogne, trascinò il più grande degli italiani, Galileo, sull'altare dell'impostura", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La fratellanza umana è impossibile coi preti.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La maggior parte delle guerre, e le più sanguinose, furono, e sono fomentate dai preti.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il Bonaparte, nemico di tutte le libertà, e protettore di tutti i tiranni, volle, come per saggio, provare le sue armi contro Roma", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Morte a nessuno!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Tra le astuzie dei sardanapali pretini, ricchissimi com'eran, fu sempre mercé la stupidità dei fedeli, non ultima fu quella d'impiegare gli artisti più eminenti nell'illustrazione delle loro favole.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Salve!, valoroso popolo del Messico!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Oh! Roma!, patria dell'anima!, tu sei veramente la sola!, l'eterna!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Certo non provò tanta soddisfazione Colombo nella scoperta dell'America, come ne provai io al ritrovare chi s'occupasse della redenzione patria.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "È sempre la storia di Socrate, di Cristo e di Colombo!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Libertà non fallisce ai volenti.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Se sorgesse una società del demonio, che combattesse despoti e preti, mi arruolerei nelle sue file.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Io non devo dar principio a narrare della mia vita, senza far cenno de' miei buoni genitori", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il 7 settembre un figlio del popolo, accompagnato da pochi suoi amici che si chiamavano aiutanti, entrava nella superba capitale dal focoso destriero", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "A Napoli, come in tutti i paesi percorsi dallo Stretto Di Messina, le popolazioni furono sublimi d'entusiasmo e d'amor patrio", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Quello che più mi urtava nei maneggi di cotesto partito era di trovare le tracce in certi individui che mi erano cari, e di cui mai avrei dubitato.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "I pochi giorni passati in Napoli, dopo l'accoglienza gentile fattami da quel popolo generoso, furono piuttosto di nausea, appunto per le mene e sollecitudini di quei tali cagnotti delle monarchie", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Trattavasi di rovesciare una monarchia per sostituirla, senza volontà o capacità di far meglio per quei poveri popoli", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Tra le qualità che devono primeggiare negli ufficiali dell'esercito Italiano, oltre il valore, deve contarsi l'amabilità, che attrae e vincola l'affetto del soldato.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il valore è sempre accompagnato dalla generosità.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il valoroso soldato Italiano dev'essere magnanimo con tutti, e massime colle popolazioni tra cui soggiorna", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "I rappresentanti delle associazioni operaie italiane si sono presentati a me, in questa solitudine per offrirmi un cenno di simpatia a nome del ceto robusto e laborioso del popolo.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Cristo gettò le basi dell'uguaglianza tra gli uomini e tra i popoli e noi dobbiamo essere buoni cristiani.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Avvicinino i potenti della terra il povero popolo, ch'è pur di carne e d'ossa come loro", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Sì, le nazioni vogliono intendersi, e vogliono la fratellanza di tutti; i despoti non la vogliono.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Noi domandiamo lavoro, pane e l'amore scambievole.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Costanza nondimeno, miei cari amici. È un fatto che l'Europa non presentò mai il sublime spettacolo dell'umano ravvicinamento che essa presenta oggi.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il dispotismo sorregge la logora sua esistenza colla discordia dei popoli.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "È tempo che tutti i popoli si preparino alle supreme battaglie.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "E accoglietevi in un solo pensiero di vendetta e libertà, e fate impeto irresistibile contro i vostri oppressori.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La causa della libertà è una sola, qualunque sia il nemico che la combatta, qualunque il popolo che la difenda, qualunque sia il colore della bandiera sotto cui si schierano gli eserciti.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Coraggio! Voi siete forti, purché sappiate osare.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Le società operaie molto hanno giovato all'Italia, moltissimo devono giovare per l'avvenire; il lavoro è virtù; il lavoro è libertà; benedetti coloro che lavorano!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il lavoro ci farà liberi, la libertà ci farà grandi.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Gli uomini nella sventura sono tutti fratelli, e la causa dei popoli oppressi è una sola.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Uniamoci dunque, e la nostra voce suoni potente a scuotere i troni di tutti i despoti.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Non sono nato alle pubbliche assemblee; ma se v'è radunanza alla quale ami trovarmi, è quella degli operai.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Lavoro, Patria, Libertà: ecco il programma vostro, operai, e di tutti gli uomini che non credono creato il mondo per satollare la loro ingordigia e la loro ambizione.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Il despotismo ha saputo sempre, per i suoi fini, profittare dei pregiudizi del nazionalismo e della religione", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "È il popolo rivendicato a se stesso, libero del suo braccio e della sua coscienza che dovrà creare in Italia il nuovo elemento di progresso civile, morale ed economico.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "È un fatto consolantissimo, in mezzo alle tante sciagure che ci circondano, quello di vedere che lo spirito d'associazione va sempre più crescendo in Italia e specialmente nell'elemento dell'operaio.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Lega operaia universale", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Ch'io me ne vado in America, dicono dunque i giornali della camorra governativa e pretina", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "La repubblica è il governo della gente onesta, e se ne vide la prova in tutte le epoche.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Nemico della pena di morte ed amico della pace e della fratellanza umana, mi trovo a fare la guerra, che è l'antitesi de' miei principii.", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Un brigante onesto è un mio ideale", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "le infallibilità muoiono, ma non si piegano!", Author = "Giuseppe Garibaldi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "Soccorrere i soci infermi, questo è dovere sacro per ogni società operaia.", Author = "Giuseppe Garibaldi" },
        };
    }
}